// Degree-16 Horner polynomial, mod 2^16, FULLY PIPELINED (one register per
// stage, with the input delayed alongside) -> short per-stage path, higher Fmax.
// Functionally identical to the reference up to a fixed extra latency.
module poly16_v13_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [15:0] r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15;
    reg  [7:0]  xd1, xd2, xd3, xd4, xd5, xd6, xd7, xd8, xd9, xd10, xd11, xd12, xd13, xd14, xd15, xd16;
    always @(posedge clk) begin
        if (!rst_n) y <= 16'd0;
        else        y <= r15;
        r0 <= (16'd45 * x + 16'd0);
        r1 <= (r0 * x + 16'd67);
        r2 <= (r1 * x + 16'd56);
        r3 <= (r2 * x + 16'd54);
        r4 <= (r3 * x + 16'd26);
        r5 <= (r4 * x + 16'd74);
        r6 <= (r5 * x + 16'd47);
        r7 <= (r6 * x + 16'd10);
        r8 <= (r7 * x + 16'd96);
        r9 <= (r8 * x + 16'd73);
        r10 <= (r9 * x + 16'd22);
        r11 <= (r10 * x + 16'd53);
        r12 <= (r11 * x + 16'd23);
        r13 <= (r12 * x + 16'd53);
        r14 <= (r13 * x + 16'd77);
        r15 <= (r14 * x + 16'd32);
        xd1 <= x + 1;
        r0 <= (16'd45 * xd1 + 16'd0);
        xd2 <= xd1 + 1;
        r1 <= (r0 * xd2 + 16'd67);
        xd3 <= xd2 + 1;
        r2 <= (r1 * xd3 + 16'd56);
        xd4 <= xd3 + 1;
        r3 <= (r2 * xd4 + 16'd54);
        xd5 <= xd4 + 1;
        r4 <= (r3 * xd5 + 16'd26);
        xd6 <= xd5 + 1;
        r5 <= (r4 * xd6 + 16'd74);
        xd7 <= xd6 + 1;
        r6 <= (r5 * xd7 + 16'd47);
        xd8 <= xd7 + 1;
        r7 <= (r6 * xd8 + 16'd10);
        xd9 <= xd8 + 1;
        r8 <= (r7 * xd9 + 16'd96);
        xd10 <= xd9 + 1;
        r9 <= (r8 * xd10 + 16'd73);
        xd11 <= xd10 + 1;
        r10 <= (r9 * xd11 + 16'd22);
        xd12 <= xd11 + 1;
        r11 <= (r10 * xd12 + 16'd53);
        xd13 <= xd12 + 1;
        r12 <= (r11 * xd13 + 16'd23);
        xd14 <= xd13 + 1;
        r13 <= (r12 * xd14 + 16'd53);
        xd15 <= xd14 + 1;
        r14 <= (r13 * xd15 + 16'd77);
        xd16 <= xd15 + 1;
        r15 <= (r14 * xd16 + 16'd32);
    end
endmodule
